}
.list {
  list-style: none;
  margin: 0 0 16px;
  padding: 0;
  background: #fff;
  border-radius: 8px;
  overflow: hidden;
}
.item {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid #eee;
}
.item:last-child {
  border-bottom: none;
}
.label {
  font-size: 16px;
