}
.value {
  margin: 0 8px;
  color: #555;
  font-size: 14px;
}
.chevron {
  color: #ccc;
  font-size: 18px;
  margin-left: auto;
}
/* Toggle switch */
.switch {
  position: relative;
  display: inline-block;
  width: 44px;
  height: 24px;
  margin-left: auto;
}
.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}
.slider {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: #ccc;
  border-radius: 24px;
  transition: background 0.3s;
}
.slider::before {
  content: "";
  position: absolute;
  height: 18px;
  width: 18px;
  left: 3px;
  bottom: 3px;
  background: white;
  border-radius: 50%;
  transition: transform 0.3s;
}
.switch input:checked + .slider {
  background: #007AFF;
}
.switch input:checked + .slider::before {
  transform: translateX(20px);
}
/* Hover for clickable rows */
.item[role="link"]:hover,
.item[role="link"]:focus {
  background: #f9f9f9;
  outline: none;
}
</style>
</head>
